import { SITE_MANIFEST } from '../../src/config/siteManifest.js';

/**
 * Files regenerated by `npm run site:generate` and therefore part of the same
 * publication boundary as any data that changes route provenance/SEO dates.
 */
export const SITE_PUBLISH_ARTIFACTS = Object.freeze([
  ...SITE_MANIFEST
    .filter((route) => route.status === 'active')
    .map((route) => route.file),
  'public/sitemap.xml',
  'src/config/navRoutes.generated.js',
  'src/config/performanceRoutes.generated.js',
  'src/config/lighthouseRoutes.generated.json',
]);

export const SITE_GENERATE_COMMAND = Object.freeze(['npm', 'run', 'site:generate']);
